class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert (row, col) to position using the formula: row * n + col
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        if n == 1:
            return nums[0] + 1

        # dp[j] = number of ways to have arr1[i] = j at current position
        prev_dp = [0] * (nums[0] + 1)
        for j in range(nums[0] + 1):
            prev_dp[j] = 1

        for i in range(1, n):
            curr_dp = [0] * (nums[i] + 1)

            for curr_val in range(nums[i] + 1):
                for prev_val in range(nums[i-1] + 1):
                    # arr1[i] >= arr1[i-1] (non-decreasing)
                    if curr_val < prev_val:
                        continue

                    # arr2[i-1] >= arr2[i]
                    # nums[i-1] - arr1[i-1] >= nums[i] - arr1[i]
                    # arr1[i] - arr1[i-1] >= nums[i] - nums[i-1]
                    if curr_val - prev_val < nums[i] - nums[i-1]:
                        continue

                    curr_dp[curr_val] = (curr_dp[curr_val] + prev_dp[prev_val]) % MOD

            prev_dp = curr_dp

        return sum(prev_dp) % MOD

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store color counts for each player
        player_colors = {}

        # Initialize player_colors with empty dictionaries for each player
        for i in range(n):
            player_colors[i] = {}

        # Count balls of each color for each player
        for player, color in pick:
            if color not in player_colors[player]:
                player_colors[player][color] = 0
            player_colors[player][color] += 1

        # Count how many players win
        win_count = 0

        for player in range(n):
            # Find the maximum count of any color picked by this player
            max_count = max(player_colors[player].values()) if player_colors[player] else 0

            # Player i wins if they pick at least (i+1) balls of the same color
            if max_count >= player + 1:
                win_count += 1

        return win_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of the two options
        return min(row_flips, col_flips)
